<?php
require_once __DIR__ . '/../../includes/auth.php'; requireLogin();
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT); if (!$id) { header('Location: index.php'); exit; }
$pdo = getDbConnection(); $stmt = $pdo->prepare('SELECT * FROM customers WHERE id = ?'); $stmt->execute([$id]); $customer = $stmt->fetch(); if (!$customer) { http_response_code(404); exit('Customer not found.'); }
$services = $pdo->prepare('SELECT cs.*, COALESCE(ip.name,s.service_name) service_name FROM customer_services cs JOIN services s ON s.id = cs.service_id LEFT JOIN internet_plans ip ON ip.id=cs.plan_id WHERE cs.customer_id = ?'); $services->execute([$id]); $services = $services->fetchAll();
$billing = $pdo->prepare('SELECT b.*, COALESCE(b.service_name_snapshot,s.service_name, "Service") service_name FROM billing b LEFT JOIN customer_services cs ON cs.id = b.customer_service_id LEFT JOIN services s ON s.id = cs.service_id WHERE b.customer_id = ? ORDER BY b.created_at DESC'); $billing->execute([$id]); $billing = $billing->fetchAll();
$payments = $pdo->prepare('SELECT p.*, b.invoice_number, b.amount invoice_amount, (SELECT COALESCE(SUM(p2.amount_paid),0) FROM payments p2 WHERE p2.billing_id=b.id AND p2.verification_status="verified") total_verified FROM payments p JOIN billing b ON b.id = p.billing_id WHERE b.customer_id = ? ORDER BY p.payment_date DESC'); $payments->execute([$id]); $payments = $payments->fetchAll();
$collections = $pdo->prepare('SELECT a.status collection_status,a.remarks,a.created_at updated_at,b.invoice_number,u.full_name staff_name FROM collection_activities a JOIN collections col ON col.id=a.collection_id JOIN billing b ON b.id=col.billing_id LEFT JOIN users u ON u.id=a.staff_id WHERE col.customer_id=? ORDER BY a.created_at DESC'); $collections->execute([$id]); $collections = $collections->fetchAll();
$pageTitle = 'Customer Profile'; include __DIR__ . '/../../includes/header.php'; include __DIR__ . '/../../includes/sidebar.php';
?>
<div class="d-flex justify-content-between align-items-center mb-3"><div><h3 class="mb-0">Customer Profile</h3><small class="text-muted">View customer details, service subscriptions, and account history.</small></div><div class="d-flex gap-2 action-buttons"><a class="btn btn-outline-secondary" href="edit.php?id=<?= $id ?>">Edit</a><a class="btn btn-primary" href="add_service.php?customer_id=<?= $id ?>"><i class="mdi mdi-plus"></i> Add Another Service</a></div></div>
<?php if (!empty($_GET['msg'])): ?><div class="alert alert-success alert-dismissible fade show"><?= htmlspecialchars($_GET['msg']) ?><button class="btn-close" type="button"></button></div><?php endif; ?>
<div class="card mb-3"><div class="card-body"><div class="row"><div class="col-md-4"><small class="text-muted">Customer ID</small><div class="fw-bold"><?= htmlspecialchars($customer['account_number']) ?></div></div><div class="col-md-4"><small class="text-muted">Customer</small><div class="fw-bold"><?= htmlspecialchars($customer['full_name']) ?></div></div><div class="col-md-4"><small class="text-muted">Status</small><div><?= ucfirst($customer['status']) ?></div></div><div class="col-md-4 mt-3"><small class="text-muted">Contact</small><div><?= htmlspecialchars($customer['contact_number'] ?: '-') ?></div></div><div class="col-md-4 mt-3"><small class="text-muted">Email</small><div><?= htmlspecialchars($customer['email'] ?: '-') ?></div></div><div class="col-md-4 mt-3"><small class="text-muted">Address</small><div><?= htmlspecialchars($customer['address'] ?: '-') ?></div></div></div></div></div>
<div class="card mb-3"><div class="card-header bg-white"><strong>Services</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Service Account / Plan</th><th>Monthly Rate</th><th>Frequency</th><th>Start</th><th>Next Billing</th><th>Due Rule</th><th>Status</th></tr></thead><tbody><?php foreach ($services as $service): ?><tr><td><?= htmlspecialchars($service['service_name']) ?><br><small><?= htmlspecialchars($service['service_account_number'] ?? '') ?></small><br><a href="change_plan.php?id=<?= $service['id'] ?>">Change Plan / Schedule</a><br><a href="disconnection.php?id=<?= $service['id'] ?>">Disconnection / Reconnection</a></td><td>PHP <?= number_format((float) $service['billing_amount'], 2) ?></td><td><?= ucfirst($service['billing_frequency']) ?></td><td><?= $service['start_date'] ?></td><td><?= $service['next_billing_date'] ?: '-' ?></td><td><?= $service['due_days'] ?> days</td><td><?= ucfirst($service['status']) ?></td></tr><?php endforeach; ?><?php if (!$services): ?><tr><td colspan="7" class="text-center text-muted py-3">No services assigned.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="card mb-3"><div class="card-header bg-white"><strong>Billing History</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Invoice</th><th>Service</th><th>Period</th><th>Amount</th><th>Due Date</th><th>Status</th></tr></thead><tbody><?php foreach ($billing as $bill): ?><tr><td><?= htmlspecialchars($bill['invoice_number']) ?></td><td><?= htmlspecialchars($bill['service_name']) ?></td><td><?= $bill['billing_period_start'] ?> - <?= $bill['billing_period_end'] ?></td><td>PHP <?= number_format((float) $bill['amount'], 2) ?></td><td><?= $bill['due_date'] ?></td><td><?= ucfirst($bill['status']) ?></td></tr><?php endforeach; ?><?php if (!$billing): ?><tr><td colspan="6" class="text-center text-muted py-3">No billing history.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="card mb-3"><div class="card-header bg-white"><strong>Payment History</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Date</th><th>Invoice</th><th>Amount Paid</th><th>Outstanding Balance</th><th>Status</th></tr></thead><tbody><?php foreach ($payments as $payment): ?><tr><td><?= $payment['payment_date'] ?></td><td><?= htmlspecialchars($payment['invoice_number']) ?></td><td>PHP <?= number_format((float) $payment['amount_paid'], 2) ?></td><td>PHP <?= number_format(max(0, (float) $payment['invoice_amount'] - (float) $payment['total_verified']), 2) ?></td><td><?= ucfirst($payment['verification_status']) ?></td></tr><?php endforeach; ?><?php if (!$payments): ?><tr><td colspan="5" class="text-center text-muted py-3">No payment history.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="card"><div class="card-header bg-white"><strong>Collection History</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Date</th><th>Activity</th><th>Remarks</th><th>Staff</th></tr></thead><tbody><?php foreach ($collections as $collection): ?><tr><td><?= $collection['updated_at'] ?></td><td><?= ucfirst(str_replace('_', ' ', $collection['collection_status'])) ?></td><td><?= htmlspecialchars($collection['remarks'] ?: '-') ?></td><td><?= htmlspecialchars($collection['staff_name'] ?: '-') ?></td></tr><?php endforeach; ?><?php if (!$collections): ?><tr><td colspan="4" class="text-center text-muted py-3">No collection history.</td></tr><?php endif; ?></tbody></table></div></div>
<?php include __DIR__ . '/../../includes/footer.php'; ?>